  "supportive_card_ids": ["C06", "C08", "C12", "C09", "C01", "C11", "C17", "C03", "C07"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C06", "C08", "C12", "C09", "C01", "C11", "C17"],
  "claims": [
    {
      "claim": "Codeine, a morphinan opioid sharing the hydromorphone scaffold, had 80.5% absolute oral bioavailability in healthy subjects after oral and IV administration, directly supporting F ≥ 20% for a close structural analogue.",
      "card_ids": ["C06"]
    },
    {
      "claim": "Pentazocine, a benzomorphan opioid with phenol and tertiary amine groups like hydromorphone, showed mean systemic availability of 0.68–0.70 in cirrhotic patients, well above the 20% threshold.",
      "card_ids": ["C08", "C12"]
    },
    {
      "claim": "Meptazinol, a phenol-containing analgesic, had absolute bioavailability of 27.9% in cirrhotic patients, above the threshold.",
      "card_ids": ["C09"]
    },
    {
      "claim": "Melperone, a basic lipophilic drug, had absolute bioavailability of 54–67% in fasted healthy volunteers, supporting that basic amines with similar properties can exceed 20%.",
      "card_ids": ["C01", "C11", "C17"]
    },
    {
      "claim": "No supplied record reports F < 20%; the lowest supplied values (praziquantel 27.2%, meptazinol 27.9%) remain above the threshold.",
      "card_ids": ["C07", "C09"]
    },
    {
      "claim": "L3 oral exposure records concern ethinylestradiol Cmax/Cτ/Cmin values, not hydromorphone, and do not provide absolute bioavailability evidence for the query.",
      "card_ids": ["C30", "C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C30", "C31", "C32", "C33", "C34", "C35", "C36", "C37", "C38", "C39", "C40", "C41"]
    }
  ],
  "evidence_gaps": [
    "No direct hydromorphone absolute bioavailability record is present; prediction relies on structurally related opioids and physicochemical priors.",
    "L3 records are for ethinylestradiol and report only Cmax/Cτ/Cmin, not absolute F, and are not transferable to hydromorphone.",
    "Most high-F records come from disease populations (cirrhosis, cystic fibrosis) or different chemical classes, so transferability is inferred rather than measured.",
    "Low neutral fraction (0.1) and possible first-pass metabolism at the phenol/amine are not quantified by direct hydromorphone data."
  ],
  "decision_summary": "L3 adds only ethinylestradiol oral exposure Cmax/Cτ/Cmin records, which do not bear on hydromorphone absolute F and do not contradict the prior high prediction. Existing L1 evidence from close opioid analogues (codeine 80.5%, pentazocine 68–70%) and phenol-containing analgesics (meptazinol 27.9%) plus favorable physicochemical priors supports F ≥ 20%. Prediction remains high with moderate confidence."
}

